import{_ as t,o as a,c as n,a5 as r}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"Evidence Chain Template","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/evidence-chain.en.md","filePath":"public/downloads/worksheets/evidence-chain.en.md","lastUpdated":1795488252000}'),o={name:"public/downloads/worksheets/evidence-chain.en.md"};function i(s,e,d,h,c,l){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="evidence-chain-template" tabindex="-1">Evidence Chain Template <a class="header-anchor" href="#evidence-chain-template" aria-label="Permalink to &quot;Evidence Chain Template&quot;">​</a></h1><p>This worksheet answers one concrete question: <strong>What exactly do I know has changed?</strong></p><p>It does not require every result to improve or turn life into a score. It places samples from the same task under different conditions side by side, so you can distinguish “I can do it now”, “I still can after a few days”, and “I can use it somewhere new”.</p><p>Copy it into a private note and use one copy for each main question. Do not record passwords, identity documents, customer data, medical privacy, or unauthorised third-party information. For health, safety, legal, financial, or persistent loss-of-control concerns, contact a trusted person and a qualified professional first.</p><h2 id="_1-define-the-question" tabindex="-1">1. Define the Question <a class="header-anchor" href="#_1-define-the-question" aria-label="Permalink to &quot;1. Define the Question&quot;">​</a></h2><p>Record start date:<br> Real situation and audience/user:<br> The one question this record answers:<br> Acceptance standard:<br> Possible risks and stop conditions:</p><p>The question should be observable, such as “Can I explain a project risk in English without a script and answer one follow-up?” Do not write “Am I better now?”</p><h2 id="_2-save-an-unaided-baseline" tabindex="-1">2. Save an Unaided Baseline <a class="header-anchor" href="#_2-save-an-unaided-baseline" aria-label="Permalink to &quot;2. Save an Unaided Baseline&quot;">​</a></h2><p>The baseline should happen before AI, peer feedback, or concentrated training whenever possible. Record the conditions so tools, extra time, and familiar material do not disappear from the comparison.</p><table tabindex="0"><thead><tr><th>Date</th><th>Task and constraints</th><th>Tool used?</th><th>Result/errors</th><th>Raw evidence location</th></tr></thead><tbody><tr><td></td><td></td><td>No</td><td></td><td></td></tr></tbody></table><p>What I could complete independently at baseline:<br> Where I stopped or needed a prompt:<br> What the baseline cannot prove:</p><h2 id="_3-record-immediate-performance" tabindex="-1">3. Record Immediate Performance <a class="header-anchor" href="#_3-record-immediate-performance" aria-label="Permalink to &quot;3. Record Immediate Performance&quot;">​</a></h2><p>Immediate performance says what happened under the current conditions. It does not automatically say that ability is stable.</p><table tabindex="0"><thead><tr><th>Date</th><th>Conditions and prompts</th><th>What I completed</th><th>Quality/time/rework</th><th>Evidence location</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>If AI was used, state what it did and what you completed independently after closing it. A chat log is a process trace, not proof of ability by itself.</p><h2 id="_4-test-delayed-retention" tabindex="-1">4. Test Delayed Retention <a class="header-anchor" href="#_4-test-delayed-retention" aria-label="Permalink to &quot;4. Test Delayed Retention&quot;">​</a></h2><p>Wait for a period, remove recent prompts and the original answer, and complete a related task. Choose the interval according to the task and your capacity, but write it down.</p><p>Retest date:<br> Time since the last practice:<br> Prompts removed:<br> Related task:<br> Independent result:<br> Errors that remained:<br> Evidence location:</p><h2 id="_5-test-transfer" tabindex="-1">5. Test Transfer <a class="header-anchor" href="#_5-test-transfer" aria-label="Permalink to &quot;5. Test Transfer&quot;">​</a></h2><p>Keep the core action and change at least one condition: topic, listener, time limit, material, tool permission, or purpose.</p><table tabindex="0"><thead><tr><th>Changed condition</th><th>New task</th><th>Independent result</th><th>How did the other person/user understand it?</th><th>Evidence location</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>A failed transfer does not make earlier practice worthless. It shows that the change may be too large, prerequisite knowledge is missing, or the acceptance standard needs revision.</p><h2 id="_6-separate-fact-interpretation-and-hypothesis" tabindex="-1">6. Separate Fact, Interpretation, and Hypothesis <a class="header-anchor" href="#_6-separate-fact-interpretation-and-hypothesis" aria-label="Permalink to &quot;6. Separate Fact, Interpretation, and Hypothesis&quot;">​</a></h2><p>Fact: I can point to a date, condition, sample, source, or direct observation.<br> Interpretation: How I understand those facts; it may need revision.<br> Hypothesis: The judgment I will test in the next action.<br> Conclusion I cannot draw yet:</p><p>For example, “the unaided version finished in 90 seconds” is a record. “It was clearer because my sleep improved” is an interpretation. “It may work if I can repeat it with an unfamiliar listener next week” is a hypothesis.</p><h2 id="_7-let-evidence-choose-the-next-step" tabindex="-1">7. Let Evidence Choose the Next Step <a class="header-anchor" href="#_7-let-evidence-choose-the-next-step" aria-label="Permalink to &quot;7. Let Evidence Choose the Next Step&quot;">​</a></h2><p>This evidence most supports: continue / downgrade / change one variable / pause or stop<br> The one condition I will change:<br> Smallest next task:<br> Acceptance standard for the next task:<br> Support, permission, or professional judgment needed:<br> Next review date:</p><p>When evidence conflicts, do not hide the conflict in an average. Write the different conditions first, then decide whether another sample is worth collecting. When evidence is thin, shrinking the question is usually more honest than manufacturing a precise score.</p><h2 id="_8-handover-summary" tabindex="-1">8. Handover Summary <a class="header-anchor" href="#_8-handover-summary" aria-label="Permalink to &quot;8. Handover Summary&quot;">​</a></h2><p>Main question and acceptance standard:<br> Most reliable evidence:<br> Least reliable or still missing evidence:<br> Repeated errors/risks:<br> Smallest next task and stop condition:<br> Evidence folder or link:</p><p>When handing this summary to your future self, a peer, or AI, ask them to work only from this record. They should not pretend to remember another session or fill in facts that are not present.</p><p>Related chapters: <a href="https://byoungd.github.io/up/en/threads/part-3/5-evidence-and-transfer" target="_blank" rel="noreferrer">Evidence: How Change Becomes Visible</a> | <a href="https://byoungd.github.io/up/en/templates/toolkit" target="_blank" rel="noreferrer">Toolkit Overview</a> | <a href="https://byoungd.github.io/up/en/templates/rhythm-ledger" target="_blank" rel="noreferrer">Rhythm Ledger</a> | <a href="https://byoungd.github.io/up/en/reference/glossary" target="_blank" rel="noreferrer">Glossary of Terms and Methods</a></p><hr><p>Source: <a href="https://byoungd.github.io/up/en/templates/evidence-chain" target="_blank" rel="noreferrer">Still Here</a> · Manuscript updated: 2026-09-01. Content: <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>.</p>',34)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
